    "bot_manage.approval.delete": "\u5220\u9664 Bot {id} \u548C\u5B83\u7684\u9884\u8BBE\uFF1F{memoryWarning} \u4F1A\u8BDD\u5386\u53F2\u4FDD\u7559\uFF0C\u4F46\u9700\u8981\u91CD\u65B0\u521B\u5EFA\u76F8\u540C ID \u7684 Bot \u540E\u624D\u80FD\u6062\u590D\u3002{selfWarning}",
    "bot_manage.approval.deleteMemories": "\u8B66\u544A\uFF1AdeleteMemories=true\uFF0C\u5C06\u5220\u9664\u6B64 Bot \u5F53\u524D\u7684\u5168\u90E8 {count} \u6761\u8BB0\u5FC6\uFF08\u5BA1\u6279\u524D\u7EDF\u8BA1\uFF09\uFF01",
    "bot_manage.approval.keepMemories": "deleteMemories=false\uFF0C\u4FDD\u7559\u5168\u90E8\u8BB0\u5FC6\u3002",
